from copy import deepcopy
from datetime import date
from math import isfinite


def _parse_day(value):
    if not isinstance(value, str):
        raise ValueError("invalid day")
    try:
        parsed = date.fromisoformat(value)
    except ValueError as exc:
        raise ValueError("invalid day") from exc
    if parsed.isoformat() != value:
        raise ValueError("invalid day")
    return parsed


def _price(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool) and isfinite(value)


def _fit(rows):
    return {
        field: (min(row[field] for row in rows), max(row[field] for row in rows))
        for field in ("open", "close")
    }


def _scale(rows, scaler):
    result = deepcopy(rows)
    for row in result:
        for field, (low, high) in scaler.items():
            row[field] = 0.0 if high == low else (row[field] - low) / (high - low)
    return result


def prepare_quotes(rows, cutoff):
    if not isinstance(rows, list):
        raise ValueError("invalid rows")
    cutoff_day = _parse_day(cutoff)
    parsed_days = []
    for row in rows:
        if not isinstance(row, dict) or not {"day", "open", "close"}.issubset(row):
            raise ValueError("invalid row")
        parsed_days.append(_parse_day(row["day"]))
        if not _price(row["open"]) or not _price(row["close"]):
            raise ValueError("invalid price")
    if any(a >= b for a, b in zip(parsed_days, parsed_days[1:])):
        raise ValueError("days must increase")
    derived = []
    for current, following in zip(rows, rows[1:]):
        item = deepcopy(current)
        change = following["close"] - current["close"]
        item["next_close"] = deepcopy(following["close"])
        item["change"] = change
        item["direction"] = (change > 0) - (change < 0)
        item["fractional_change"] = None if current["close"] == 0 else change / current["close"]
        derived.append(item)
    train_raw = [row for row in derived if _parse_day(row["day"]) <= cutoff_day]
    test_raw = [row for row in derived if _parse_day(row["day"]) > cutoff_day]
    if not train_raw:
        raise ValueError("empty training partition")
    scaler = _fit(train_raw)
    test_scaler = _fit(test_raw) if test_raw else scaler
    return {"scaler": deepcopy(scaler), "train": _scale(train_raw, scaler), "test": _scale(test_raw, test_scaler)}

